SELECT id, name, product_id AS productId, parts_id AS partsId, icon_url AS iconUrl, sub_images AS subImages, detail, spec_param AS specParam, price, stock, status, is_hot AS isHot, created, updated FROM product WHERE 1=1
AND p.id = #{id}
AND p.name LIKE CONCAT('%', #{name}, '%')
AND p.status = #{status}
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM product p
WHERE 1=1

    AND p.id = #{id}


    AND p.name LIKE CONCAT('%', #{name}, '%')


    AND p.status = #{status}

